function median(a) { var s = a.slice().sort(function (x, y) { return x - y; }); return s[(s.length / 2) | 0]; }
var med = median(readings);
var devs = readings.map(function (r) { return Math.abs(r - med); });
var worst = 0;
devs.forEach(function (d, i) { if (d > devs[worst]) worst = i; });
var spread = Math.max.apply(null, devs);
var faulty = spread > med * 0.1 ? worst : -1;
if (faulty >= 0) console.log("Isolated faulty unit: sensor " + (faulty + 1) + " (dev " + devs[faulty].toFixed(2) + " vs median " + med.toFixed(2) + ")");
else console.log("No faulty unit: all agree within 10%.");
console.log("Isolation steps: " + DATA.steps);
console.log("RESULT: " + (faulty >= 0 ? "fault isolated to sensor " + (faulty + 1) : "no fault") + ".");
